import { DomainError } from "./DomainError";

export class Product {
  public constructor(
    public readonly id: string,
    public readonly name: string,
    private stock: number,
  ) {
    if (!id.trim() || !name.trim()) {
      throw new DomainError("Product id and name are required");
    }
    if (!Number.isInteger(stock) || stock < 0) {
      throw new DomainError("Stock must be a non-negative integer");
    }
  }

  public get availableStock(): number {
    return this.stock;
  }

  public reserve(quantity: number): void {
    this.assertValidQuantity(quantity);
    if (this.stock < quantity) {
      throw new DomainError(`Insufficient stock for product ${this.id}`);
    }
    this.stock -= quantity;
  }

  public release(quantity: number): void {
    this.assertValidQuantity(quantity);
    this.stock += quantity;
  }

  private assertValidQuantity(quantity: number): void {
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new DomainError("Quantity must be a positive integer");
    }
  }
}

